### 🧠 2. Backend (Node.js + Express + MongoDB)

#### ➤ `backend/server.js`
```js
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
const admissionRoutes = require('./routes/admissionRoutes');

const app = express();
const PORT = 5000;

app.use(cors());
app.use(express.json());
app.use('/api/admissions', admissionRoutes);

// MongoDB connection
mongoose.connect('mongodb://localhost:27017/college', {
  useNewUrlParser: true,
  useUnifiedTopology: true
}).then(() => console.log('MongoDB connected'))
  .catch(err => console.log(err));

app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

#### ➤ `backend/models/Admission.js`
```js
const mongoose = require('mongoose');

const AdmissionSchema = new mongoose.Schema({
  name: String,
  email: String,
  course: String,
  message: String
});

module.exports = mongoose.model('Admission', AdmissionSchema);
```

#### ➤ `backend/routes/admissionRoutes.js`
```js
const express = require('express');
const router = express.Router();
const Admission = require('../models/Admission');

// POST - Submit form
router.post('/', async (req, res) => {
  try {
    const admission = new Admission(req.body);
    await admission.save();
    res.status(201).send("Form submitted successfully");
  } catch (error) {
    res.status(400).send("Error saving form");
  }
});

// GET - View all forms
router.get('/', async (req, res) => {
  const admissions = await Admission.find();
  res.json(admissions);
});

module.exports = router;
```

---

### 🎨 3. Frontend (`public/index.html`)

Use the responsive, Tailwind-based code we already built above. Add this **admission form** to the bottom:

```html
<!-- Admission Form -->
<section class="bg-white text-black py-10 px-6 max-w-3xl mx-auto rounded-lg shadow-xl">
  <h2 class="text-2xl font-bold mb-4 text-richred">Admission Enquiry Form</h2>
  <form id="admissionForm" class="space-y-4">
    <input type="text" name="name" placeholder="Your Name" required class="w-full p-2 border rounded">
    <input type="email" name="email" placeholder="Your Email" required class="w-full p-2 border rounded">
    <input type="text" name="course" placeholder="Interested Course" required class="w-full p-2 border rounded">
    <textarea name="message" placeholder="Message" rows="4" class="w-full p-2 border rounded"></textarea>
    <button type="submit" class="bg-richred text-white px-6 py-2 rounded hover:bg-red-700 transition">Submit</button>
  </form>
  <p id="formMsg" class="mt-4 text-sm"></p>
</section>
```

#### ➤ Add this JS in `<script>` at the bottom:
```html
<script>
  const form = document.getElementById('admissionForm');
  const msg = document.getElementById('formMsg');

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const data = Object.fromEntries(new FormData(form));

    try {
      const res = await fetch('http://localhost:5000/api/admissions', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(data)
      });

      if (res.ok) {
        msg.textContent = "Form submitted successfully!";
        msg.classList.add('text-green-600');
        form.reset();
      } else {
        msg.textContent = "Submission failed. Try again.";
        msg.classList.add('text-red-600');
      }
    } catch (err) {
      msg.textContent = "Server error. Please try later.";
      msg.classList.add('text-red-600');
    }
  });
</script>
```

---

## 🚀 Running Your Full-Stack Website Locally

1. **Install backend dependencies**
   ```bash
   npm init -y
   npm install express mongoose cors
   ```

2. **Start MongoDB** (via `mongod`)

3. **Run the backend**
   ```bash
   node backend/server.js
   ```

4. **Open `index.html` in browser** (it will make API requests to `localhost:5000`)

