Here's how you can implement the insertion of a node at the beginning of a linked list in C++ without using functions:

```cpp
#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

int main() {
    // Initial linked list is empty
    Node* head = nullptr;

    // Inserting first node at the beginning
    Node* newNode = new Node();
    newNode->data = 1;
    newNode->next = head;  // Since the list is empty, head is nullptr
    head = newNode;

    // Inserting second node at the beginning
    newNode = new Node();
    newNode->data = 2;
    newNode->next = head;
    head = newNode;

    // Inserting third node at the beginning
    newNode = new Node();
    newNode->data = 3;
    newNode->next = head;
    head = newNode;

    // Printing the linked list
    Node* current = head;
    while (current != nullptr) {
        cout << current->data << " -> ";
        current = current->next;
    }
    cout << "nullptr" << endl;

    return 0;
}
```

### Explanation:
- **Node Structure**: Defines a node with an integer `data` and a pointer `next` to the next node.
- **head**: A pointer that initially points to `nullptr`, indicating an empty list.
- **Insertion**: Nodes are inserted at the beginning by creating a new node, pointing its `next` to the current `head`, and then updating the `head` to this new node.
- **Printing**: Iterates through the list and prints each node's data until it reaches the end (`nullptr`).

### Example Output:
```
