A **singly linked list** is a type of linked list where each node points to the next node in the sequence, but not to the previous one. Here’s a simple implementation of a singly linked list in C++:

```cpp
#include <iostream>
using namespace std;

// Node class representing each element in the linked list
class Node {
public:
    int data;   // Data part
    Node* next; // Pointer to the next node

    // Constructor to create a new node
    Node(int data) {
        this->data = data;
        this->next = nullptr;
    }
};

// LinkedList class to manage the linked list
class LinkedList {
private:
    Node* head; // Pointer to the first node in the list

public:
    // Constructor to initialize an empty list
    LinkedList() {
        head = nullptr;
    }

    // Function to append a new node at the end of the list
    void append(int data) {
        Node* new_node = new Node(data); // Create a new node
        if (!head) { // If the list is empty, set the new node as the head
            head = new_node;
            return;
        }
        Node* last = head;
        while (last->next) { // Traverse to the last node
            last = last->next;
        }
        last->next = new_node; // Point the last node's next to the new node
    }

    // Function to prepend a new node at the beginning of the list
    void prepend(int data) {
        Node* new_node = new Node(data); // Create a new node
        new_node->next = head; // Set the new node's next to the current head
        head = new_node; // Set the new node as the head
    }

    // Function to delete a node with a specific value
    void deleteWithValue(int data) {
        if (!head) return; // If the list is empty, return

        // If the node to be deleted is the head
        if (head->data == data) {
            Node* temp = head;
            head = head->next; // Move the head to the next node
            delete temp; // Delete the old head
            return;
        }

        // Traverse the list to find the node to delete
        Node* temp = head;
        while (temp->next && temp->next->data != data) {
            temp = temp->next;
        }

        // If the node to delete is found
        if (temp->next) {
            Node* nodeToDelete = temp->next;
            temp->next = temp->next->next; // Remove the node from the list
            delete nodeToDelete; // Delete the node
        }
    }

    // Function to display the list
    void display() {
        Node* temp = head;
        while (temp) {
            cout << temp->data << " -> ";
            temp = temp->next;
        }
        cout << "NULL" << endl;
    }
};

int main() {
    LinkedList list;

    list.append(10);   // Add 10 to the end
    list.append(20);   // Add 20 to the end
    list.append(30);   // Add 30 to the end

    list.prepend(5);   // Add 5 to the beginning

    cout << "Linked List: ";
    list.display();    // Display the list

    list.deleteWithValue(20); // Delete the node with value 20
    cout << "After Deletion: ";
    list.display();    // Display the list again

    return 0;
}
```

### Explanation:

1. **Node Class**:
   - Represents each element in the linked list.
   - Contains `data` and a pointer to the next `Node`.

2. **LinkedList Class**:
   - Manages the singly linked list.
   - `head`: Points to the first node in the list.

3. **append()**:
   - Adds a new node with the specified data to the end of the list.

4. **prepend()**:
   - Adds a new node at the beginning of the list.

5. **deleteWithValue()**:
   - Deletes the first node with the specified value from the list.

6. **display()**:
   - Prints the elements of the list.

