Here's a simple implementation of a linear queue using an array in C++:

### Implementation of a Linear Queue in C++

```cpp
#include <iostream>
using namespace std;

class Queue {
private:
    int front, rear, size;
    int* queue;

public:
    Queue(int s) {
        front = -1;
        rear = -1;
        size = s;
        queue = new int[size];
    }

    ~Queue() {
        delete[] queue;
    }

    bool isEmpty() {
        return front == -1;
    }

    bool isFull() {
        return rear == size - 1;
    }

    void enqueue(int item) {
        if (isFull()) {
            cout << "Queue is full\n";
            return;
        }
        if (front == -1) {
            front = 0;
        }
        rear++;
        queue[rear] = item;
        cout << item << " enqueued to queue\n";
    }

    int dequeue() {
        if (isEmpty()) {
            cout << "Queue is empty\n";
            return -1;
        }
        int item = queue[front];
        if (front == rear) {
            front = rear = -1; // Queue becomes empty
        } else {
            front++;
        }
        cout << item << " dequeued from queue\n";
        return item;
    }

    int peek() {
        if (isEmpty()) {
            cout << "Queue is empty\n";
            return -1;
        }
        return queue[front];
    }

    void display() {
        if (isEmpty()) {
            cout << "Queue is empty\n";
            return;
        }
        cout << "Queue contents: ";
        for (int i = front; i <= rear; i++) {
            cout << queue[i] << " ";
        }
        cout << endl;
    }
};

int main() {
    Queue q(5);

    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);

    q.display(); // Output: Queue contents: 10 20 30

    q.dequeue(); // Output: 10 dequeued from queue

    q.display(); // Output: Queue contents: 20 30

    cout << "Front item is: " << q.peek() << endl; // Output: Front item is: 20

    return 0;
}
```

### Explanation:

1. **Queue Class**:
    - The class contains an array `queue` to store the elements.
    - `front` and `rear` keep track of the front and rear positions of the queue.
    - `size` is the maximum size of the queue.

2. **Constructor**:
    - Initializes `front` and `rear` to `-1`, indicating an empty queue.
    - Dynamically allocates an array of the given size.

3. **Destructor**:
    - Frees the allocated memory to avoid memory leaks.

4. **isEmpty()**:
    - Returns `true` if

