        queue[rear] = item;
        cout << item << " enqueued to queue\n";
    }

    int dequeue() {
        if (isEmpty()) {
            cout << "Queue is empty\n";
            return -1;
        }
        int item = queue[front];
        if (front == rear) {
            front = rear = -1; // Queue becomes empty
        } else {
            front++;
        }
        cout << item << " dequeued from queue\n";
        return item;
    }

    int peek() {
        if (isEmpty()) {
            cout << "Queue is empty\n";
            return -1;
        }
        return queue[front];
    }

    void display() {
        if (isEmpty()) {
            cout << "Queue is empty\n";
            return;
        }
        cout << "Queue contents: ";
        for (int i = front; i <= rear; i++) {
            cout << queue[i] << " ";
        }
        cout << endl;
    }
};

int main() {
    Queue q(5);

    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);

    q.display(); // Output: Queue contents: 10 20 30

    q.dequeue(); // Output: 10 dequeued from queue

    q.display(); // Output: Queue contents: 20 30

    cout << "Front item is: " << q.peek() << endl; // Output: Front item is: 20

    return 0;
}
```

### Explanation:

- **Struct**: The queue is implemented using a `struct`, which defaults to public access for all its members.
- **Members**:
  - `front`, `rear`, and `size` are used to manage the queue.
  - `queue` is a pointer to the dynamically allocated array.
- **Constructor**: Initializes the `front` and `rear` indices and allocates memory for the array.
- **Destructor**: Frees the dynamically allocated memory.
- **Operations**:
  - `isEmpty()` checks if the queue is empty.
  - `isFull()` checks if the queue is full.
  - `enqueue()` adds an element to the rear of the queue.
  - `dequeue()` removes an element from the front of the queue.
  - `peek()` returns the front element without removing it.
  - `display()` shows the current contents of the queue.
